/* ============ V6 ============ */
sim('bore','Bohrungsprüfung mit Rotiersensor','Der Sensor dreht in der Bohrung und tastet den Umfang ab. Verstelle die Risslage und stelle die <b>Prüffrequenz deutlich über die Drehfrequenz</b>. Der Hochpass entfernt den Exzentrizitäts-Anteil (Abhebung), nur kurze Rissimpulse bleiben.',b=>{
 const P={rpm:3000,f:500,D:10,hp:true,cr:[70,210],ecc:.5};let th=0;
 const cols=h('div',{cls:'cols'});b.append(cols);
 const A=cvs(cols,{ar:.92,draw:(c,w,hh)=>{G.bench(c,w,hh);const cx=w/2,cy=hh*.5,R=Math.min(w,hh)*.3;
  // Bauteil mit Bohrung (Draufsicht, leicht perspektivisch)
  c.save();c.shadowColor=T.shadow;c.shadowBlur=18;c.shadowOffsetY=8;G.metal(c,cx-R*1.55,cy-R*1.55,R*3.1,R*3.1,'alu',{r:R*.25});c.restore();
  c.save();G.rr(c,cx-R*1.55,cy-R*1.55,R*3.1,R*3.1,R*.25);c.clip();
  const g=c.createRadialGradient(cx,cy-R*.15,R*.2,cx,cy,R*1.05);g.addColorStop(0,'#06090c');g.addColorStop(.75,'#2b3540');g.addColorStop(.93,'#7d8b98');g.addColorStop(1,'#c9d3dc');c.fillStyle=g;c.beginPath();c.arc(cx,cy,R*1.05,0,TAU);c.fill();
  c.strokeStyle='rgba(255,255,255,.7)';c.lineWidth=2;c.beginPath();c.arc(cx,cy,R*1.05,.65*Math.PI,1.55*Math.PI);c.stroke();
  P.cr.forEach(a=>{const ca=Math.cos(a*D2R),sa=-Math.sin(a*D2R);c.strokeStyle='#0d1013';c.lineWidth=2.2;c.lineCap='round';c.beginPath();let x=cx+ca*R*1.05,y=cy+sa*R*1.05;c.moveTo(x,y);srand(a);for(let k=1;k<=6;k++){const rr=R*(1.05+k*.07);x=cx+ca*rr+(rnd()-.5)*3;y=cy+sa*rr+(rnd()-.5)*3;c.lineTo(x,y)}c.stroke();
   });c.restore();P.cr.forEach(a=>{const ca=Math.cos(a*D2R),sa=-Math.sin(a*D2R);G.label(c,'Riss '+a+'°',clamp(cx+ca*R*1.45,40,w-40),clamp(cy+sa*R*1.45,30,hh-14),{align:'center',size:10.5,col:T.red})});
  // Rotor
  const ex=P.ecc*R*.08*Math.cos(th*.13),sx=cx+ex,sy=cy;c.save();c.translate(sx,sy);c.rotate(-th);const hr=R*.86;
  const gr=c.createLinearGradient(-hr,0,hr,0);gr.addColorStop(0,'#1b2c3d');gr.addColorStop(.5,'#3e6f9c');gr.addColorStop(1,'#1b2c3d');c.fillStyle=gr;c.beginPath();c.arc(0,0,hr,0,TAU);c.fill();c.strokeStyle='rgba(255,255,255,.25)';c.lineWidth=1;c.stroke();
  for(let k=0;k<6;k++){c.strokeStyle='rgba(255,255,255,.08)';c.beginPath();c.moveTo(0,0);c.lineTo(Math.cos(k*TAU/6)*hr,Math.sin(k*TAU/6)*hr);c.stroke()}
  const near=P.cr.some(a=>{const d=Math.abs((((th/D2R)%360)-a+540)%360-180);return d<8});G.metal(c,hr*.55,-hr*.16,hr*.42,hr*.32,'ferrite',{r:4});c.strokeStyle=near?'#ff5d6c':'#ffc58f';c.lineWidth=2.5;c.shadowColor=near?'#ff3b4a':'#ffb000';c.shadowBlur=near?16:8;c.beginPath();c.ellipse(hr*.76,0,hr*.12,hr*.1,0,0,TAU);c.stroke();c.restore();
  // Abtastspur
  c.save();c.strokeStyle=G.rgba(T.teal,.65);c.lineWidth=3;c.beginPath();c.arc(cx,cy,R*.98,-th-.9,-th);c.stroke();c.restore();
  G.dot(c,cx,cy,4,'#cfd8e0',{ring:false});G.label(c,'Bohrung Ø '+P.D+' mm · '+P.rpm+' U/min',cx,16,{align:'center',size:11.5,col:T.ink2})}});
 const B=cvs(cols,{ar:.92,dark:true,draw:(c,w,hh)=>{const S=G.screen(c,0,0,w,hh,{label:'Signal über 3 Umdrehungen',bezel:7,nx:12,ny:8});const m=mapper({x:S.x+6,y:S.y+22,w:S.w-12,h:S.h-30},[0,3],[-1.25,1.25]);const fr=P.rpm/60,q=P.f*1000/fr,wd=clamp(8*Math.min(1,300/q+.2),4,40);
  const sig=u=>{const a=(u%1)*360;let y=P.hp?0:P.ecc*Math.sin(TAU*u+.8);P.cr.forEach(ca=>{let d=Math.abs(((a-ca)%360+540)%360-180);y+=Math.exp(-Math.pow(d/wd,2))*Math.min(1,q/30)});return y};
  const u0=((th/TAU)%3+3)%3;const p=[],p2=[];for(let i=0;i<=900;i++){const u=i/300;(u<=u0?p:p2).push([m.x(u),m.y(sig(u))])}G.trace(c,p2,G.rgba(PH.g,.35),1.3,{blur:2});G.trace(c,p,PH.g,1.8);G.spot(c,m.x(u0),m.y(sig(u0)),PH.g,3.5);
  for(let i=1;i<3;i++)G.line(c,[[m.x(i),S.y+20],[m.x(i),S.y+S.h-4]],G.rgba(PH.a,.5),1,{dash:[4,4]});G.glass(c,S);
  u('fr',fmt(fr,0)+' Hz');u('q',fmt(q,0)+' ×',q>=10?'g':'r');u('s',q>=30?'sauber':q>=10?'brauchbar':'verschmiert – Frequenz zu niedrig',q>=10?'g':'r');u('rec',P.D<=3?'2 MHz empfohlen (Ø ≤ 3 mm)':'≈ 0,5 MHz üblich')}});
 animate(B,dt=>{th+=TAU*P.rpm/60*dt*.02;A.redraw()});const cr=h('div',{cls:'ctls'});b.append(cr);slider(cr,{label:'Drehzahl',min:600,max:6000,step:100,value:3000,unit:'U/min',on:v=>P.rpm=v});slider(cr,{label:'Prüffrequenz',min:20,max:2500,log:true,value:500,unit:'kHz',on:v=>P.f=v});slider(cr,{label:'Bohrungsdurchmesser',min:1,max:20,step:.5,value:10,unit:'mm',on:v=>P.D=v});slider(cr,{label:'Riss 1 Lage',min:0,max:359,step:1,value:70,unit:'°',on:v=>P.cr[0]=v});slider(cr,{label:'Riss 2 Lage',min:0,max:359,step:1,value:210,unit:'°',on:v=>P.cr[1]=v});slider(cr,{label:'Exzentrizität / Abhebung',min:0,max:1,step:.05,value:.5,fmt:v=>fmt(v*100,0)+' %',on:v=>P.ecc=v});
 seg(b,[[true,'Hochpass ein'],[false,'ohne Filter']],true,v=>P.hp=v);const u=readouts(b,[['fr','Drehfrequenz'],['q','f_Prüf / f_Dreh'],['s','Signalqualität'],['rec','Frequenzempfehlung']]);
 b.append(h('div',{cls:'cap'},'Rotiersensor nicht zu klein wählen (sonst ungleichmäßiger Abhebeeffekt). Mit Teflonklebeband: Spulendurchmesser höchstens 0,3 mm kleiner als die Bohrung.'))});

sim('korr6','Korrosionsprüfung an Blechüberlappungen','Absolutspule über dem Blech: <b>Lift-off nach links</b>, <b>Korrosionsabtrag (Wanddickenverlust) nach oben</b>, <b>Aufbeulung nach rechts</b> – dafür muss die Frequenz stimmen. Kalibriere mit den 4 Referenzstufen und bestimme den unbekannten Abtrag per Interpolation. Lackschichten >50 µm verfälschen!',b=>{
 const P={ab:15,beul:0,lack:0,f:6,ph:0,comp:false};const refs=[5,10,20,30];const dl=()=>30+60*(1-Math.exp(-P.f/5));
 const vec=(ab,beul,lack)=>{let v=Cx.pol(.7*(1-Math.exp(-lack/90)),Math.PI);const A=1-Math.exp(-ab/16);v=Cx.add(v,Cx.pol(.8*A*Math.exp(-lack/500),(180-dl())*D2R));v=Cx.add(v,Cx.pol(beul/250*.9,dl()*D2R));return Cx.mul(v,Cx.pol(1,P.ph*D2R))};
 // Schnittbild
 const X=cvs(b,{ar:w=>w<620?.42:.22,draw:(c,w,hh)=>{G.bench(c,w,hh);const x0=w*.04,x1=w*.96,y=hh*.42,t1=hh*.17,t2=hh*.17;const bul=P.beul/250*hh*.12;
  // unteres Blech
  G.metal(c,x0+w*.25,y+t1+3,x1-x0-w*.25,t2,'alu',{hatch:.1});
  // Korrosion an Fügefläche
  const cx=w*.6,cwid=w*.22,dep=P.ab/100*t1;c.save();c.beginPath();c.moveTo(x0,y);for(let x=x0;x<=x1;x+=4){const k=Math.exp(-Math.pow((x-cx)/(cwid*.5),4));c.lineTo(x,y-bul*k)}c.lineTo(x1,y+t1);for(let x=x1;x>=x0;x-=4){const k=Math.exp(-Math.pow((x-cx)/(cwid*.5),4));c.lineTo(x,y+t1-dep*k)}c.closePath();c.clip();G.metal(c,x0,y-bul-2,x1-x0,t1+bul+4,'alu',{hatch:.1});c.restore();
  c.fillStyle='#b4683a';c.beginPath();for(let x=cx-cwid*.6;x<=cx+cwid*.6;x+=3){const k=Math.exp(-Math.pow((x-cx)/(cwid*.5),4));c.lineTo(x,y+t1-dep*k-1)}for(let x=cx+cwid*.6;x>=cx-cwid*.6;x-=3){const k=Math.exp(-Math.pow((x-cx)/(cwid*.5),4));c.lineTo(x,y+t1+3+bul*k*.5)}c.closePath();c.fill();
  srand(4);c.fillStyle='#e0a274';for(let i=0;i<40;i++){const x=cx+(rnd()-.5)*cwid,k=Math.exp(-Math.pow((x-cx)/(cwid*.5),4));if(k>.2)c.fillRect(x,y+t1-dep*k+rnd()*(dep*k+2),2,2)}
  if(P.lack>0){c.fillStyle='rgba(235,190,60,.9)';c.beginPath();const lt=Math.min(10,P.lack/12);for(let x=x0;x<=x1;x+=4){const k=Math.exp(-Math.pow((x-cx)/(cwid*.5),4));c.lineTo(x,y-bul*k-lt)}for(let x=x1;x>=x0;x-=4){const k=Math.exp(-Math.pow((x-cx)/(cwid*.5),4));c.lineTo(x,y-bul*k)}c.closePath();c.fill()}
  // Niet
  [x0+w*.33,x1-w*.05].forEach(nx=>{c.fillStyle='#8d99a5';c.beginPath();c.ellipse(nx,y-1,9,5,0,Math.PI,0);c.fill();c.fillRect(nx-4,y,8,t1+t2+3)});
  G.probe(c,cx,y-bul-(P.lack>0?Math.min(10,P.lack/12):0)-2,Math.min(30,hh*.2),{len:hh*.3,cable:false,I:.5});
  G.label(c,'Korrosion '+P.ab+' %',cx+cwid*.55,y+t1+t2*.5,{size:10.5,col:'#a5582e'});if(P.beul>0)G.label(c,'Aufbeulung',cx-cwid*.62,y-bul-10,{align:'right',size:10.5,col:T.blue});G.text(c,'Deckblech',x0+4,y+t1*.65,{size:10.5,weight:700,col:'#2a3540'})}});
 const O=cvs(b,{ar:w=>w<620?1.3:.56,dark:true,draw:(c,w,hh)=>{c.fillStyle='#0b1218';c.fillRect(0,0,w,hh);const narrow=w<620;const sw=narrow?w:w*.5;const S=G.screen(c,4,4,sw-8,narrow?w*.8:hh-8,{label:'Impedanzebene',bezel:7});const cx=S.cx,cy=S.cy,Sc=Math.min(S.w,S.h)/2*.78;
  const draw1=(v,col,l)=>{G.arrow(c,cx,cy,cx+v[0]*Sc,cy-v[1]*Sc,col,{lw:2.4,glow:8});G.stext(c,l,cx+v[0]*Sc+(v[0]<0?-6:6),cy-v[1]*Sc-6,{col,size:10.5,align:v[0]<0?'right':'left'})};draw1(vec(0,0,60),PH.a,'Lift-off');draw1(vec(P.ab,0,0),PH.g,'Abtrag');draw1(vec(0,200,0),PH.b,'Aufbeulung');
  const cur=vec(P.ab,P.beul,P.lack);G.spot(c,cx+cur[0]*Sc,cy-cur[1]*Sc,'#ffffff',4.5);G.glass(c,S);
  const Q=narrow?{x:44,y:w*.8+30,w:w-58,h:hh-w*.8-76}:{x:sw+44,y:20,w:w-sw-58,h:hh-66};const sv=T;T=PAL.dark;const m=G.plot(c,Q,[0,35],[0,1],{nx:7,ny:4,xl:'Abtrag in %',yl:'Y-Höhe',xf:v=>fmt(v,0),yf:v=>fmt(v,1),yo:32,bgc:'#101a23',title:'Kalibrierkurve'});T=sv;
  const Y=ab=>vec(ab,0,0)[1];const pts=[];for(let a=0;a<=35;a+=1)pts.push([m.x(a),m.y(clamp(Y(a),0,1))]);G.line(c,pts,'#6b7f92',1.2,{dash:[3,3]});const cp=refs.map(a=>[m.x(a),m.y(clamp(Y(a),0,1))]);G.trace(c,cp,PH.g,2);cp.forEach((p,i)=>{G.spot(c,p[0],p[1],PH.g,2.5);G.stext(c,refs[i]+'%',p[0]+5,p[1]+14,{size:9.5})});
  const yy=cur[1]/(P.comp?Math.exp(-P.lack/500):1);G.line(c,[[Q.x,m.y(clamp(yy,0,1))],[m.x(P.ab),m.y(clamp(yy,0,1))]],G.rgba(PH.a,.7),1,{dash:[3,3]});G.spot(c,m.x(P.ab),m.y(clamp(cur[1],0,1)),PH.a,3.5);
  let est=null;const ys=refs.map(a=>Y(a));for(let i=0;i<refs.length-1;i++){if((yy-ys[i])*(yy-ys[i+1])<=0){est=lerp(refs[i],refs[i+1],(yy-ys[i])/(ys[i+1]-ys[i]))}}if(est==null)est=yy<ys[0]?refs[0]*yy/ys[0]:refs[3];
  u('est',fmt(est,1)+' %',Math.abs(est-P.ab)<2.5?'g':'r');u('w',P.ab+' %');u('ang','Δ Lift-off↔Abtrag = '+fmt(dl(),0)+'°',Math.abs(dl()-90)<18?'g':'');u('hint',P.lack>50&&!P.comp?'Lack >50 µm: mit Folie referenzieren!':P.lack>0&&P.lack<=50?'Lack <50 µm darf vernachlässigt werden':'–',P.lack>50&&!P.comp?'r':'')}});
 const cr=h('div',{cls:'ctls'});b.append(cr);const rd=()=>{O.redraw();X.redraw()};slider(cr,{label:'wahrer Abtrag (Rückseite)',min:0,max:35,step:.5,value:15,unit:'%',on:v=>{P.ab=v;rd()}});slider(cr,{label:'Aufbeulung',min:0,max:250,step:5,value:0,unit:'µm',on:v=>{P.beul=v;rd()}});slider(cr,{label:'Farbschicht',min:0,max:150,step:5,value:0,unit:'µm',on:v=>{P.lack=v;rd()}});slider(cr,{label:'Prüffrequenz',min:.5,max:30,log:true,value:6,unit:'kHz',on:v=>{P.f=v;rd()}});slider(cr,{label:'Phasensteller',min:-90,max:90,step:1,value:0,unit:'°',on:v=>{P.ph=v;rd()}});
 seg(b,[[false,'ohne Folienreferenz'],[true,'Schicht mit Folie referenziert']],false,v=>{P.comp=v;rd()});const u=readouts(b,[['w','wahrer Abtrag'],['est','Messwert (Interpolation)'],['ang','Winkel'],['hint','Hinweis']]);setTimeout(rd,60)});

