sim('tube','Rohr durch die Spule führen: Absolut, Differenz, Doppel- und Mehrfachdifferenz','Ziehe das Rohr nach links/rechts durch das Spulensystem. Wähle kurze oder lange Fehler und schalte <b>Wackeln</b> und <b>Temperaturdrift</b> zu. Welche Schaltung zeigt den langen Fehler dauerhaft? Welche unterdrückt Wackeln und Drift?',b=>{
 const P={sys:'diff',len:6,wob:0,drift:0,pos:-150,dep:1};const sg=9,a=22,u0=0;
 const Sabs=x=>{let s=0;for(let u=u0-10;u<=u0+P.len+10;u+=1){const d=(u>=u0&&u<=u0+P.len)?P.dep:0;if(d)s+=Math.exp(-Math.pow((x-u)/sg,2)/2)}s/=(sg*2.5066);return s+P.wob*.5*Math.sin(x/8)+P.drift*x/300};
 const S=x=>{switch(P.sys){case'abs':return Sabs(x);case'diff':return Sabs(x-a/2)-Sabs(x+a/2);case'dd':return(Sabs(x-a)-2*Sabs(x)+Sabs(x+a))*-1;default:return(Sabs(x-1.5*a)-Sabs(x-.5*a)+Sabs(x+.5*a)-Sabs(x+1.5*a))*.9}};
 const O=cvs(b,{ar:.7,arNarrow:1,draw:(c,w,hh)=>{G.bench(c,w,hh);const sh=hh*.4,cy=sh*.52,k=w/420,ox=w/2;const X=v=>ox+v*k;const tr=Math.min(sh*.16,26);
  const coils={abs:[0],diff:[-a/2,a/2],dd:[-a,0,a],md:[-1.5*a,-.5*a,.5*a,1.5*a]}[P.sys];const wob=P.wob*Math.sin(P.pos/8)*tr*.25;
  coils.forEach(x=>G.ringCoil(c,X(x),cy,tr*.38,tr*1.55,a*k*.55,'back',{n:4}));
  G.tube(c,-10,w+10,cy+wob,tr,'steel',{endL:false});c.save();const fx=X(P.pos+u0),fw=Math.max(3,P.len*k);const gd=c.createLinearGradient(0,cy-tr,0,cy-tr*.3);gd.addColorStop(0,'#1a0d0d');gd.addColorStop(1,'rgba(214,40,57,.4)');c.fillStyle=gd;G.rr(c,fx,cy+wob-tr,fw,tr*.6,2);c.fill();c.restore();
  coils.forEach((x,i)=>{const s=S(0-P.pos);G.ringCoil(c,X(x),cy,tr*.38,tr*1.55,a*k*.55,'front',{n:4,glow:Math.abs(s)>.02?T.teal:null});const sgn=(P.sys==='diff'&&i===1)||(P.sys==='dd'&&i===1)||(P.sys==='md'&&i%2===1)?'−':'+';G.badge(c,P.sys==='dd'&&i===1?'−2':sgn,X(x),cy-tr*1.55-14,sgn==='+'?T.blue:T.orange,{align:'center'})});
  G.label(c,'⇆ Rohr mit dem Fehler (rot) ziehen',10,sh-12,{size:10.5,col:T.mute});
  const R={x:46,y:sh+14,w:w-60,h:hh-sh-58};const ymax=Math.max(.001,...Array.from({length:84},(_,i)=>Math.abs(S(-210+i*5-P.pos))))*1.18;const m=G.plot(c,R,[-210,210],[-ymax,ymax],{nx:6,ny:2,xl:'Rohrposition relativ zur Spule in mm',xf:v=>fmt(v,0),yf:()=>'',zero:true,title:'Signal'});
  const pts=[];for(let x=-210;x<=210;x+=2)pts.push([m.x(x),m.y(S(x-P.pos))]);c.save();c.beginPath();c.rect(R.x,R.y,R.w,R.h);c.clip();G.curve(c,pts,T.blue,{lw:2.4,fill:m.y(0),fa:.15});c.restore();G.vline(c,m,0,T.faint);G.dot(c,m.x(0),m.y(clamp(S(0-P.pos),-ymax,ymax)),6,T.orange)}});
 O.drag((x,y,t)=>{if(t==='down'||t==='move'){P.pos=clamp((x-O.w/2)/(O.w/420),-200,200);O.redraw()}});
 const cr=h('div',{cls:'ctls'});b.append(cr);const rd=()=>O.redraw();slider(cr,{label:'Fehlerlänge',min:1,max:150,log:true,value:6,unit:'mm',on:v=>{P.len=v;rd()}});slider(cr,{label:'Wackeln (Abstand)',min:0,max:1,step:.05,value:0,fmt:v=>fmt(v*100,0)+' %',on:v=>{P.wob=v;rd()}});slider(cr,{label:'Temperaturdrift',min:0,max:1,step:.05,value:0,fmt:v=>fmt(v*100,0)+' %',on:v=>{P.drift=v;rd()}});
 seg(b,[['abs','Absolutsystem'],['diff','Differenz'],['dd','Doppeldifferenz'],['md','Mehrfachdifferenz']],'diff',v=>{P.sys=v;rd()});b.append(h('div',{cls:'cap'},'Differenzspulen reagieren auf kurze Fehler (und die Enden langer Fehler), Absolutspulen liefern bei langen Fehlern ein Dauersignal – aber auch Wackel-, Temperatur- und Abhebeeffekte.'))});

sim('fill','Füllungsgrad und Wackeleffekt','Wähle Außen- oder Innendurchlaufsensor und stelle Durchmesser und Exzentrizität (Wackeln) ein. Große Füllungsgrade → geringe Wackeleffekte, hohe und gleichmäßige Empfindlichkeit, großer Stör-Nutz-Abstand.',b=>{
 const P={DP:30,DS:34,off:0,type:'out'};const eta=()=>P.type==='out'?Math.pow(P.DP/P.DS,2):Math.pow(P.DS/P.DP,2);let t=0;
 const O=cvs(b,{ar:w=>w<620?1.05:.48,draw:(c,w,hh)=>{G.bench(c,w,hh);const narrow=w<620;const cx=narrow?w/2:w*.26,cy=narrow?hh*.27:hh/2,sc=Math.min(narrow?w*.2:w*.2,narrow?hh*.22:hh*.4)/Math.max(P.DP,P.DS);const out=P.type==='out';const Rs=P.DS/2*sc,Rp=P.DP/2*sc,ox=P.off*sc*.5*Math.sin(t*2.2);
  const ring=(r,wd)=>{const g=c.createRadialGradient(cx,cy,r-wd,cx,cy,r+wd);g.addColorStop(0,'#8d4a1f');g.addColorStop(.5,'#ffc58f');g.addColorStop(1,'#8d4a1f');c.strokeStyle=g;c.lineWidth=wd*2;c.beginPath();c.arc(cx,cy,r,0,TAU);c.stroke();for(let k=0;k<36;k++){const a=k/36*TAU;G.winding(c,cx+Math.cos(a)*r,cy+Math.sin(a)*r,wd*.75,0)}};
  // Prüfgut im Schnitt
  c.save();c.translate(cx+ox,cy);const gp=c.createRadialGradient(-Rp*.3,-Rp*.3,Rp*.1,0,0,Rp);gp.addColorStop(0,'#dbe2e8');gp.addColorStop(1,'#7b8794');c.fillStyle=gp;c.beginPath();c.arc(0,0,Rp,0,TAU);if(out){c.arc(0,0,Rp*.72,0,TAU,true)}c.fill('evenodd');G.hatch(c,-Rp,-Rp,2*Rp,2*Rp,'rgba(0,0,0,.08)',6);c.restore();
  if(out){c.save();c.fillStyle=DARK?'#0e1520':'#edf2f7';c.beginPath();c.arc(cx+ox,cy,Rp*.72,0,TAU);c.fill();c.restore()}
  ring(Rs,Math.max(4,Math.min(9,Rs*.08)));
  // Luftspalt hervorheben
  c.save();c.fillStyle=G.rgba(T.red,.12);c.beginPath();c.arc(cx,cy,out?Rs:Rp,0,TAU);c.arc(cx+(out?ox:0),cy,out?Rp:Rs,0,TAU,true);c.fill('evenodd');c.restore();
  G.label(c,out?'Außendurchlaufsensor':'Innendurchlaufsensor',cx,narrow?hh*.53:hh-16,{align:'center',size:11.5,col:T.ink2});
  const e=eta();const bx=narrow?24:w*.55,bw=narrow?w-48:w*.4,by=narrow?hh*.62:hh*.18,st=narrow?hh*.09:hh*.2;const wob=P.off*(1-e)*.25;
  G.meterBar(c,bx,by,bw,14,e,e>=(out?.5:.8)?T.green:T.red,'Füllungsgrad η',fmt(e*100,0)+' %');G.meterBar(c,bx,by+st,bw,14,e,T.blue,'Empfindlichkeit',fmt(e*100,0)+' %');G.meterBar(c,bx,by+2*st,bw,14,clamp(wob*2.5,0,1),T.orange,'Wackel-Störsignal',fmt(clamp(wob*2.5,0,1)*100,0)+' %');G.meterBar(c,bx,by+3*st,bw,14,clamp(e*(1-wob*2),0,1),T.violet,'Stör-Nutz-Abstand',fmt(clamp(e*(1-wob*2),0,1)*100,0)+' %');
  u('e',fmt(e,2),(out?e>=.5:e>=.8)?'g':'r');u('b',out?(e>=.95?'sehr hoch (Grenze 0,95)':e>=.5?'üblich 0,5 … 0,95':'zu klein für Fehlerprüfung'):(e>=.9?'optimal (≥ 0,9)':e>=.8?'noch zulässig (≥ 0,8)':'zu klein (< 0,8)'),(out?e>=.5:e>=.8)?'g':'r')}});
 animate(O,dt=>{t+=dt});
 const cr=h('div',{cls:'ctls'});b.append(cr);const rd=()=>O.redraw();slider(cr,{label:'Prüfgut-Durchmesser D_P',min:10,max:60,step:1,value:30,unit:'mm',on:v=>{P.DP=v;rd()}});slider(cr,{label:'Spulen-Durchmesser D_S',min:10,max:60,step:1,value:34,unit:'mm',on:v=>{P.DS=v;rd()}});slider(cr,{label:'Wackeln (Exzentrizität)',min:0,max:10,step:.5,value:0,unit:'mm',on:v=>{P.off=v;rd()}});
 seg(b,[['out','Außendurchlaufsensor: η = (D_P/D_S)²'],['in','Innendurchlaufsensor: η = (D_S/D_P)²']],'out',v=>{P.type=v;rd()});const u=readouts(b,[['e','Füllungsgrad η'],['b','Bewertung']])});

sim('spiral','Spiralvorschub und Rotiersensor: Überdeckung','Der Rotiersensor tastet das Rohr schraubenförmig ab. Die <b>Ganghöhe</b> (Vorschub je Umdrehung) muss kleiner als die Abtastbreite sein, sonst bleiben Streifen ungeprüft.',b=>{
 const P={v:30,n:600,w:12,D:40};let t=0;const O=cvs(b,{ar:w=>w<620?1:.56,draw:(c,w,hh)=>{const pitch=P.v*1000/P.n;const circ=Math.PI*P.D;G.bench(c,w,hh);const narrow=w<620;
  // 3D-Rohr mit Schraubenspur
  const top=narrow?hh*.38:hh*.42,cy=top*.5,r=Math.min(top*.32,40),x0=24,x1=w-24,Lmm=pitch*6;const k=(x1-x0)/Lmm;
  G.tube(c,x0,x1,cy,r,'steel');c.save();c.beginPath();c.rect(x0,cy-r,x1-x0,2*r);c.clip();
  for(let s=-1;s<8;s++){c.beginPath();for(let a=0;a<=1;a+=.01){const x=x0+(s+a)*pitch*k-((t*.3)%1)*pitch*k,ang=a*TAU;const z=Math.cos(ang);if(z<0){c.moveTo(x,cy-Math.sin(ang)*r);continue}c.lineTo(x,cy-Math.sin(ang)*r)}c.strokeStyle=G.rgba(T.teal,.55);c.lineWidth=Math.max(2,P.w*k);c.stroke()}c.restore();
  const hx=x0+(x1-x0)*.5;c.save();c.shadowColor=T.shadow;c.shadowBlur=10;G.metal(c,hx-r*.5,cy-r-26,r,20,'plastic',{r:6});c.restore();G.text(c,'Rotierkopf',hx,cy-r-32,{align:'center',size:11,weight:700,col:T.ink2});
  // abgewickelte Oberfläche
  const R=narrow?{x:30,y:top+14,w:w-44,h:hh-top-56}:{x:30,y:top+14,w:w-44,h:hh-top-56};const kx=R.w/Lmm,ky=R.h/circ;c.save();G.metal(c,R.x,R.y,R.w,R.h,'steel',{r:4});c.beginPath();c.rect(R.x,R.y,R.w,R.h);c.clip();
  if(pitch>P.w){c.fillStyle=G.rgba(T.red,.28);c.fillRect(R.x,R.y,R.w,R.h)}c.strokeStyle=G.rgba(T.teal,.8);c.lineWidth=Math.max(1,P.w*kx*Math.cos(Math.atan2(R.h,pitch*kx)));for(let i=-1;i<8;i++){c.beginPath();c.moveTo(R.x+i*pitch*kx,R.y+R.h);c.lineTo(R.x+(i+1)*pitch*kx,R.y);c.stroke()}c.restore();
  G.dim(c,R.x,R.y-6,R.x+pitch*kx,R.y-6,'Ganghöhe '+fmt(pitch,1)+' mm',{size:10});G.text(c,'abgewickelte Rohroberfläche (Umfang π·D = '+fmt(circ,0)+' mm, senkrecht) · rot = ungeprüft',R.x,R.y+R.h+18,{size:11,col:T.mute});
  const ov=(P.w-pitch)/P.w;u('p',fmt(pitch,1)+' mm',pitch<=P.w?'g':'r');u('w',P.w+' mm');u('o',pitch<=P.w?fmt(ov*100,0)+' % Überdeckung':fmt(100*(pitch-P.w)/pitch,0)+' % ungeprüft',pitch<=P.w?'g':'r')}});
 animate(O,dt=>{t+=dt});
 const cr=h('div',{cls:'ctls'});b.append(cr);const rd=()=>O.redraw();slider(cr,{label:'Vorschub v',min:1,max:120,step:1,value:30,unit:'m/min',on:v=>{P.v=v;rd()}});slider(cr,{label:'Drehzahl n',min:100,max:3000,step:50,value:600,unit:'U/min',on:v=>{P.n=v;rd()}});slider(cr,{label:'Abtastbreite (Wirkbreite)',min:2,max:40,step:1,value:12,unit:'mm',on:v=>{P.w=v;rd()}});slider(cr,{label:'Rohrdurchmesser',min:10,max:120,step:1,value:40,unit:'mm',on:v=>{P.D=v;rd()}});const u=readouts(b,[['p','Ganghöhe = v/n'],['w','Wirkbreite'],['o','Ergebnis']])});

