sim('layer','Schichtdickenmessung: Justieren und Messen mit Einflussgrößen','Das Gerät (Wirbelstrom auf Aluminium, Lift-off als Messgröße) wird <b>nullgestellt</b> bzw. zweipunkt-justiert. Miss dann mit verschiedenen Störeinflüssen. Raue Oberfläche: Mittelwert aus ca. 10 Messungen und Nullmessung auf gleichrauem unbeschichtetem Stück!',b=>{
 const P={t:50,cal:'none',geo:'flat',rough:0,sig:35,T:20,emi:false,mean:false,zeroRough:false};const sigcal=35,Tcal=20;let last=null,anim=0;
 const bias=()=>{let d=0;d+=-6*Math.log(P.sig/sigcal);d+={flat:0,edge:12,convex:9,concave:-10}[P.geo];d+=P.zeroRough?0:.9*P.rough;d+=.15*(P.T-Tcal);return d};
 const meas=()=>{const sd=(P.cal==='none'?.03:P.cal==='one'?.02:.01)*P.t+.3+(P.emi?6:0)+(P.mean?0:P.rough*.35);let n=P.mean?10:1,s=0;for(let i=0;i<n;i++)s+=P.t+bias()+gauss()*sd*(P.cal==='none'?1.2:1);let v=s/n;if(P.cal==='none')v+=3*(P.t/60);return Math.max(0,v)};
 const O=cvs(b,{ar:w=>w<620?1.1:.48,draw:(c,w,hh)=>{G.bench(c,w,hh);const narrow=w<620;
  // Probe im Schnitt
  const S=narrow?{x:16,y:16,w:w-32,h:hh*.42}:{x:18,y:18,w:w*.48,h:hh-36};const by=S.y+S.h*.62,bh=S.h*.3;const geoY=x=>{const u=(x-S.x)/S.w-.5;return P.geo==='convex'?u*u*S.h*.25:P.geo==='concave'?-u*u*S.h*.25:0};
  c.save();c.beginPath();c.moveTo(S.x,by+geoY(S.x));for(let x=S.x;x<=S.x+(P.geo==='edge'?S.w*.62:S.w);x+=3){const rr=P.rough?Math.abs(Math.sin(x*.9)+Math.sin(x*2.3)*.5)*P.rough*.18:0;c.lineTo(x,by+geoY(x)-rr)}const xe=P.geo==='edge'?S.x+S.w*.62:S.x+S.w;c.lineTo(xe,by+bh);c.lineTo(S.x,by+bh);c.closePath();c.clip();G.metal(c,S.x,by-S.h*.3,S.w,bh+S.h*.3,'alu',{hatch:.1});c.restore();
  const tpx=Math.max(2,P.t*.12);c.save();c.fillStyle='rgba(240,185,50,.9)';c.beginPath();for(let x=S.x;x<=xe;x+=3){const rr=P.rough?Math.abs(Math.sin(x*.9)+Math.sin(x*2.3)*.5)*P.rough*.18:0;c.lineTo(x,by+geoY(x)-rr*.4-tpx)}for(let x=xe;x>=S.x;x-=3){const rr=P.rough?Math.abs(Math.sin(x*.9)+Math.sin(x*2.3)*.5)*P.rough*.18:0;c.lineTo(x,by+geoY(x)-rr)}c.closePath();c.fill();c.restore();
  const px=P.geo==='edge'?xe-18:S.x+S.w*.5;const drop=Math.sin(anim*Math.PI)*0;G.probe(c,px,by+geoY(px)-tpx-1,Math.min(38,S.h*.18),{len:S.h*.42,I:.6});if(P.emi){G.text(c,'📱',S.x+S.w-30,S.y+30,{size:24});c.strokeStyle=G.rgba(T.red,.6);for(let k=1;k<4;k++){c.beginPath();c.arc(S.x+S.w-18,S.y+22,k*10,Math.PI*.6,Math.PI*1.2);c.stroke()}}
  G.label(c,'Schicht '+P.t+' µm · σ = '+fmtg(P.sig)+' MS/m',S.x+S.w/2,S.y+S.h-10,{align:'center',size:11});
  // Gerät
  const D=narrow?{x:16,y:S.y+S.h+14,w:w-32,h:hh-S.h-46}:{x:w*.53,y:18,w:w*.47-18,h:hh-36};c.save();c.shadowColor=T.shadow;c.shadowBlur=18;c.shadowOffsetY=6;const gd=c.createLinearGradient(0,D.y,0,D.y+D.h);gd.addColorStop(0,'#33414f');gd.addColorStop(1,'#18212a');c.fillStyle=gd;G.rr(c,D.x,D.y,D.w,D.h,18);c.fill();c.restore();
  G.text(c,'SCHICHTDICKE · Wirbelstrom',D.x+16,D.y+22,{size:10.5,weight:800,col:'#9fb3c8'});G.text(c,{none:'Werk',one:'1-Pkt',two:'2-Pkt'}[P.cal],D.x+D.w-16,D.y+22,{size:10.5,weight:800,col:'#5eead4',align:'right'});
  const L={x:D.x+16,y:D.y+32,w:D.w-32,h:D.h*.38};const gl=c.createLinearGradient(0,L.y,0,L.y+L.h);gl.addColorStop(0,'#c9d9b0');gl.addColorStop(1,'#a9bd8c');c.fillStyle=gl;G.rr(c,L.x,L.y,L.w,L.h,8);c.fill();
  c.font=G.font(Math.min(L.h*.55,44),700,true);c.textAlign='right';c.fillStyle='rgba(20,30,10,.055)';c.fillText('888,8',L.x+L.w-48,L.y+L.h*.7);c.fillStyle='#1e2a12';c.fillText(last==null?'––,–':fmt(last,1),L.x+L.w-48,L.y+L.h*.7);G.text(c,'µm',L.x+L.w-12,L.y+L.h*.7,{size:13,weight:800,col:'#1e2a12',align:'right'});if(P.mean)G.text(c,'x̄ n=10',L.x+10,L.y+16,{size:10,weight:800,col:'#3b4a22'});
  const e=last==null?null:last-P.t,tol=Math.max(.1*P.t,1.5);const ok=e!=null&&Math.abs(e)<=tol;G.led(c,D.x+26,L.y+L.h+20,ok,'#3dff95',6,'OK');G.led(c,D.x+62,L.y+L.h+20,e!=null&&!ok,'#ff3b4a',6,'TOL');
  G.text(c,e==null?'▶ Messen drücken':'Abweichung '+(e>=0?'+':'')+fmt(e,1)+' µm ('+fmt(100*e/P.t,0)+' %)',D.x+D.w/2,L.y+L.h+56,{align:'center',size:13.5,weight:800,col:e==null?'#9fb3c8':ok?'#3dff95':'#ff7b86'});
  G.text(c,'Norm: ±10 % bzw. ±1,5 µm (der größere Wert)',D.x+D.w/2,L.y+L.h+76,{align:'center',size:10.5,col:'#8fa6b8'});G.text(c,'systematischer Einfluss: '+(bias()>=0?'+':'')+fmt(bias(),1)+' µm',D.x+D.w/2,L.y+L.h+94,{align:'center',size:11,weight:700,col:'#ffb36b'})}});
 const cr=h('div',{cls:'ctls'});b.append(cr);const rd=()=>O.redraw();slider(cr,{label:'wahre Schichtdicke',min:5,max:150,step:1,value:50,unit:'µm',on:v=>{P.t=v;last=null;rd()}});slider(cr,{label:'Leitfähigkeit Grundwerkstoff',min:3,max:58,log:true,value:35,unit:'MS/m',on:v=>{P.sig=v;rd()}});slider(cr,{label:'Rauheit (Spitzen)',min:0,max:30,step:1,value:0,unit:'µm',on:v=>{P.rough=v;rd()}});slider(cr,{label:'Temperatur Gerät/Teil',min:0,max:80,step:1,value:20,unit:'°C',on:v=>{P.T=v;rd()}});
 seg(b,[['none','Werkseinstellung'],['one','Einpunkt (Nullmessung)'],['two','Zweipunkt (Null + Folie)']],'none',v=>{P.cal=v;rd()});seg(b,[['flat','ebene Fläche'],['edge','nahe Kante'],['convex','konvex'],['concave','konkav']],'flat',v=>{P.geo=v;rd()});seg(b,[[false,'ohne Störfeld'],[true,'Mobiltelefon / Sender in der Nähe']],false,v=>{P.emi=v;rd()});seg(b,[[false,'Einzelmessung'],[true,'Mittelwert aus 10']],false,v=>{P.mean=v;rd()});seg(b,[[false,'Nullmessung auf glatt'],[true,'Nullmessung auf gleich rauem Stück']],false,v=>{P.zeroRough=v;rd()});
 btn(b,'▶ Messen',()=>{last=meas();rd()},'ok');b.append(h('div',{cls:'cap'},'Werkseinstellung ca. ±3 %/5 µm, Einpunkt ca. 2 %, Zweipunkt ca. 1 % vom Messwert (Skript). Geometrieeffekte: kleiner „Luftanteil“ → positive Fehler (Kante, konvex), größerer Anteil → negative Fehler (konkav).'))});

sim('mcal','Mehrpunkt-Kalibrierkurve am Universalgerät (Lift-off als Messgröße)','Der Lift-off wird in die senkrechte Achse gelegt. Gemessen wurde an 6 Folien (0–74 µm). Stelle die unbekannte Schichtdicke ein, lies die Bildschirmhöhe ab und bestimme die Dicke per Interpolation. Die Alarmschwelle für die Mindestschichtdicke wird aus der Kurve abgeleitet.',b=>{
 const cal=[[0,10],[18,30],[32,45],[48,60],[62,72],[74,83]];const P={t:40,min:40};const pct=t=>{for(let i=0;i<cal.length-1;i++)if(t<=cal[i+1][0])return lerp(cal[i][1],cal[i+1][1],(t-cal[i][0])/(cal[i+1][0]-cal[i][0]));return cal[5][1]+(t-74)*.45};
 const inv=p=>{for(let i=0;i<cal.length-1;i++)if(p<=cal[i+1][1])return lerp(cal[i][0],cal[i+1][0],(p-cal[i][1])/(cal[i+1][1]-cal[i][1]));return 74+(p-83)/.45};
 const O=cvs(b,{ar:w=>w<620?1.1:.52,draw:(c,w,hh)=>{G.bench(c,w,hh,{dots:false});const narrow=w<620;const sw=narrow?w*.5:w*.26;const S=G.screen(c,10,10,sw,narrow?sw*1.1:hh-20,{label:'Gerät',bezel:7,nx:4,ny:10});const p=pct(P.t),thr=pct(P.min);
  const yy=v=>S.y+S.h-6-v/100*(S.h-24);G.line(c,[[S.x,yy(thr)],[S.x+S.w,yy(thr)]],G.rgba(PH.r,.85),1.5,{dash:[6,4]});G.stext(c,'Alarm',S.x+S.w-6,yy(thr)-5,{align:'right',col:PH.r,size:10});
  const tr=[];for(let k=0;k<=20;k++)tr.push([S.cx,yy(10+(p-10)*k/20)]);G.trace(c,tr,PH.g,2);G.spot(c,S.cx,yy(p),p>=thr?PH.g:PH.r,4.5);G.stext(c,fmt(p,0)+' %',S.cx+10,yy(p)+4,{col:PH.g,size:12});G.glass(c,S);
  const R=narrow?{x:50,y:S.y+S.h+24,w:w-64,h:hh-S.h-80}:{x:sw+70,y:16,w:w-sw-86,h:hh-60};const m=G.plot(c,R,[0,80],[0,100],{nx:8,ny:5,xl:'Schichtdicke in µm',yl:'Bildschirmhöhe in %',xf:v=>fmt(v,0),yf:v=>fmt(v,0),yo:38,title:'Kalibrierkurve aus 6 Folien'});
  G.curve(c,cal.map(q=>[m.x(q[0]),m.y(q[1])]),T.blue,{lw:2.4,fill:R.y+R.h,fa:.12});cal.forEach(q=>{G.dot(c,m.x(q[0]),m.y(q[1]),5,T.blue);G.label(c,q[0]+' µm',m.x(q[0]),m.y(q[1])+16,{align:'center',size:9.5,col:T.mute,shadow:false})});
  G.hline(c,m,thr,T.red,{dash:[6,4],lw:1.6});G.label(c,'Alarmschwelle '+fmt(thr,0)+' % (min. '+P.min+' µm)',R.x+R.w-6,m.y(thr)-12,{align:'right',size:10.5,col:T.red});
  G.line(c,[[m.x(P.t),R.y+R.h],[m.x(P.t),m.y(p)],[R.x,m.y(p)]],T.orange,1.6,{dash:[4,3]});G.dot(c,m.x(P.t),m.y(p),7,T.orange,{halo:4});
  u('p',fmt(p,0)+' %');u('t',fmt(inv(p),0)+' µm');u('ok',P.t>=P.min?'Schicht ausreichend':'Mindestdicke unterschritten – Alarm',P.t>=P.min?'g':'r')}});
 const cr=h('div',{cls:'ctls'});b.append(cr);slider(cr,{label:'unbekannte Schichtdicke',min:0,max:80,step:1,value:40,unit:'µm',on:v=>{P.t=v;O.redraw()}});slider(cr,{label:'geforderte Mindestschichtdicke',min:10,max:70,step:1,value:40,unit:'µm',on:v=>{P.min=v;O.redraw()}});const u=readouts(b,[['p','Anzeige am Bildschirm'],['t','Ablesung aus Kalibrierkurve'],['ok','Bewertung']])});

