sim('justage','Justierung nach DIN EN ISO 17643 (ferritische Werkstoffe)','Am Vergleichskörper mit 0,5 / 1 / 2 mm tiefen Nuten: Die <b>1-mm-Nut</b> auf <b>80 %</b> Bildschirmhöhe stellen, die 0,5-mm-Nut muss ≥ 50 % davon erreichen (max. 6 dB). Frequenz 100 kHz–1 MHz. Eine Beschichtung (max. 2 mm, gleichmäßig) wird durch Verstärkung ausgeglichen.',b=>{
 const P={f:300,g:0,c:0};const A=d=>{const de=1.5*Math.sqrt(100/P.f);return 100*1.17*Math.pow(10,P.g/20)*Math.exp(-P.c/.72)*(1-Math.exp(-d/de))};let t=0;
 const O=cvs(b,{ar:w=>w<620?1.05:.52,draw:(c,w,hh)=>{G.bench(c,w,hh);const narrow=w<620;
  // Vergleichskörper
  const K=narrow?{x:16,y:24,w:w-32,h:hh*.3}:{x:18,y:30,w:w*.44,h:hh*.5};G.slab(c,K.x,K.y+K.h*.35,K.w-30,K.h*.55,30,K.h*.3,'steel',{hatch:.08});
  if(P.c>0){c.fillStyle='rgba(60,90,160,.75)';const ct=Math.min(14,P.c*6);c.beginPath();c.moveTo(K.x,K.y+K.h*.35);c.lineTo(K.x+K.w-30,K.y+K.h*.35);c.lineTo(K.x+K.w,K.y+K.h*.05);c.lineTo(K.x+30,K.y+K.h*.05);c.closePath();c.globalAlpha=.55;c.fill();c.globalAlpha=1;c.fillRect(K.x,K.y+K.h*.35-ct,K.w-30,ct)}
  [[.5,'0,5'],[1,'1'],[2,'2']].forEach(([d,l],i)=>{const x=K.x+(K.w-30)*(.22+i*.28),dep=d*K.h*.12;c.fillStyle='#14181d';c.fillRect(x-1.5,K.y+K.h*.35,3,dep);c.strokeStyle='rgba(20,24,29,.75)';c.lineWidth=1.6;c.beginPath();c.moveTo(x,K.y+K.h*.35);c.lineTo(x+30,K.y+K.h*.05);c.stroke();G.label(c,l+' mm',x,K.y+K.h*.35+dep+14,{align:'center',size:10.5,col:T.ink2})});
  const pp=(Math.sin(t*.8)*.5+.5);const prx=K.x+(K.w-30)*(.12+pp*.76)+15;G.probe(c,prx,K.y+K.h*.2-(P.c>0?Math.min(14,P.c*6):0),Math.min(30,K.h*.22),{len:K.h*.5,cable:false,I:.5});G.text(c,'Vergleichskörper (ferritisch)',K.x,K.y-6,{size:11.5,weight:700,col:T.ink2});
  // Balkenanzeige
  const R=narrow?{x:50,y:K.y+K.h+40,w:w-64,h:hh-K.h-96}:{x:w*.5+50,y:20,w:w*.5-66,h:hh-66};const m=G.plot(c,R,[0,3],[0,110],{xt:[],ny:5,yl:'Bildschirmhöhe in %',yf:v=>fmt(v,0),yo:38,noxl:true});
  c.fillStyle=G.rgba(T.green,.08);c.fillRect(R.x,m.y(84),R.w,m.y(76)-m.y(84));G.hline(c,m,80,T.green,{lw:1.4});G.label(c,'Soll 80 %',R.x+R.w-6,m.y(80)-12,{align:'right',size:10.5,col:T.green});
  const a1=A(1),a05=A(.5),dB=20*Math.log10(a1/a05);[[.5,'0,5 mm'],[1,'1 mm'],[2,'2 mm']].forEach(([d,l],i)=>{const a=A(d),bw=R.w*.18,x=m.x(i+.5)-bw/2,hgt=Math.min(108,a);const col=a>100?T.red:i===1?(Math.abs(a-80)<=4?T.green:T.blue):T.blue;G.bar(c,x,m.y(hgt),bw,R.y+R.h-m.y(hgt),col,{r:6});G.text(c,l,x+bw/2,R.y+R.h+16,{align:'center',size:11.5,weight:700,col:T.ink2});G.label(c,fmt(a,0)+' %',x+bw/2,m.y(hgt)-14,{align:'center',size:11,col})});
  G.line(c,[[m.x(.5),m.y(Math.min(108,a05))],[m.x(1.5),m.y(Math.min(108,a1))]],T.violet,1.4,{dash:[3,3]});G.label(c,fmt(dB,1)+' dB',m.x(1),(m.y(Math.min(108,a05))+m.y(Math.min(108,a1)))/2-10,{align:'center',size:10.5,col:dB<=6?T.green:T.red});
  const c1=Math.abs(a1-80)<=4,c2=a05/a1>=.5,c3=P.f>=100&&P.f<=1000,c4=P.c<=2;u('a',fmt(a1,0)+' %',c1?'g':'r');u('r',fmt(dB,1)+' dB',c2?'g':'r');u('f',c3?'im Normbereich':'außerhalb 100 kHz–1 MHz',c3?'g':'r');u('all',c1&&c2&&c3&&c4?'✔ Justierung erfüllt':'noch nicht erfüllt',c1&&c2&&c3&&c4?'g':'r')}});
 animate(O,dt=>{t+=dt});
 const cr=h('div',{cls:'ctls'});b.append(cr);const rd=()=>O.redraw();slider(cr,{label:'Prüffrequenz',min:10,max:2000,log:true,value:300,unit:'kHz',on:v=>{P.f=v;rd()}});slider(cr,{label:'Verstärkung',min:-6,max:30,step:.5,value:0,unit:'dB',on:v=>{P.g=v;rd()}});slider(cr,{label:'Beschichtung (nichtleitend)',min:0,max:2.5,step:.1,value:0,unit:'mm',on:v=>{P.c=v;rd()}});
 const u=readouts(b,[['a','Anzeige 1-mm-Nut (Soll 80 %)'],['r','Differenz 1 mm ↔ 0,5 mm (max. 6 dB)'],['f','Frequenz'],['all','Ergebnis']]);b.append(h('div',{cls:'cap'},'Modellhafte Darstellung. 0,5 mm Beschichtung dämpft ca. 6 dB → +6 dB Verstärkung. Nachweisgrenze „wie geschweißt“: lineare Oberflächenanzeige 1 mm tief, 5 mm lang.'))});
